insert into public.content_versions(id, content_id, version, title, body, min_age_weeks, max_age_weeks, status, sources) values ('62000000-0000-4000-8000-000000000001'::uuid, '61000000-0000-4000-8000-000000000001'::uuid, 1, 'Förbered hemmet före valpens ankomst', '## En lugn start

- Ordna en lugn viloplats där valpen kan få vara ostörd.
- Gå igenom valpens rum och plocka undan sådant som kan skada valpen eller som du inte vill att den tuggar på.
- Fråga uppfödaren om valpen har en filt eller annan trygg sak hemifrån som kan följa med.

Det här är en förberedelselista före hemkomst. Den är inte en valpålder eller ett träningsschema.', 0, 0, 'draft', ARRAY['https://www.rspca.org.uk/adviceandwelfare/pets/dogs/health/puppycare']::text[]) on conflict (id) do nothing;
insert into public.content_versions(id, content_id, version, title, body, min_age_weeks, max_age_weeks, status, sources) values ('62000000-0000-4000-8000-000000000002'::uuid, '61000000-0000-4000-8000-000000000002'::uuid, 1, 'Första veckan hemma', 'Om valpen nyligen har flyttat hem kan de första dagarna göras lugna och förutsägbara. Ge valpen en trygg viloplats, låt den utforska i egen takt och belöna sådant du gärna vill se mer av. Titta på flera kroppssignaler tillsammans och i sitt sammanhang; en enstaka signal är inte en diagnos. Ge utrymme om valpen verkar obekväm och kontakta veterinär vid oro för hälsan.', 8, 12, 'draft', ARRAY['https://www.rspca.org.uk/adviceandwelfare/pets/dogs/health/puppycare', 'https://avsab.org/wp-content/uploads/2021/08/AVSAB-Humane-Dog-Training-Position-Statement-2021.pdf', 'https://avsab.org/resources/position-statements/', 'https://www.rspca.org.uk/adviceandwelfare/pets/dogs/behaviour/understanding']::text[]) on conflict (id) do nothing;
insert into public.content_versions(id, content_id, version, title, body, min_age_weeks, max_age_weeks, status, sources) values ('62000000-0000-4000-8000-000000000003'::uuid, '61000000-0000-4000-8000-000000000003'::uuid, 1, 'Vardagslogg och rutiner i Tassla', '## Så använder du vardagsloggen

Tryck på en snabbknapp för att lägga till kiss, bajs, mat, sömn, vaken eller promenad. En post får datum och tid och kan ha en kort, frivillig anteckning.

I logghistoriken kan du se poster grupperade efter dag. Du kan ändra eller radera en post och, när det finns äldre poster, hämta fler. Hälsoposter som vikt och veterinärbesök visas under Hälsa i stället.

Loggen hjälper dig att hålla reda på det du själv registrerar. Den tolkar inte hundens behov och upptäcker inte mönster åt dig.', 0, null, 'draft', ARRAY['repo://src/features/puppy-log/README.md', 'repo://src/features/puppy-log/LogScreen.tsx']::text[]) on conflict (id) do nothing;
insert into public.content_versions(id, content_id, version, title, body, min_age_weeks, max_age_weeks, status, sources) values ('62000000-0000-4000-8000-000000000004'::uuid, '61000000-0000-4000-8000-000000000004'::uuid, 1, 'Trygg hantering bygger på frivillighet', '## Kort, lugnt och frivilligt

Låt valpen först se och nosa på handen. Belöna lugn nyfikenhet. Om valpen är bekväm kan du prova en mycket kort beröring på en plats den verkar acceptera och sedan pausa.

Låt valpen välja om den vill stanna kvar. Tvinga inte fram beröring eller fasthållning för att genomföra övningen. Målet här är en trygg vardagsvana, inte att utföra en undersökning eller behandling.

Läs flera kroppssignaler tillsammans och i sitt sammanhang; en enstaka signal är inte en diagnos. Att vända bort huvudet, slicka sig om munnen, gäspa, krypa undan eller försöka gå därifrån kan då vara tecken på obehag. Sluta då, ge utrymme och gör nästa försök lättare. Om rädsla eller svår hantering återkommer, be veterinär om hjälp att hitta rätt stöd.', 13, 16, 'draft', ARRAY['https://avsab.org/wp-content/uploads/2021/08/AVSAB-Humane-Dog-Training-Position-Statement-2021.pdf', 'https://avsab.org/resources/position-statements/', 'https://www.rspca.org.uk/adviceandwelfare/pets/dogs/behaviour/understanding']::text[]) on conflict (id) do nothing;
insert into public.content_versions(id, content_id, version, title, body, min_age_weeks, max_age_weeks, status, sources) values ('62000000-0000-4000-8000-000000000005'::uuid, '61000000-0000-4000-8000-000000000005'::uuid, 1, 'Trygghet i nya miljöer', '## Innan ni utforskar

- Börja på en lugn plats där valpen kan vila och själv välja att närma sig.
- Plocka undan sådant som kan skada valpen eller som du inte vill att den tuggar på.
- Låt nya vardagsintryck komma gradvis och på ett avstånd där valpen fortfarande verkar bekväm.
- Låt valpen titta, nosa eller gå undan; belöna frivillig nyfikenhet och lugn kontakt.
- Avsluta och skapa mer avstånd om valpen verkar orolig. Försök senare från ett lättare läge.

Socialisering handlar om positiva, gradvisa och individanpassade erfarenheter. Valpen behöver inte hälsa på allt.', 17, 26, 'draft', ARRAY['https://www.rspca.org.uk/adviceandwelfare/pets/dogs/health/puppycare', 'https://avsab.org/wp-content/uploads/2024/12/Puppy-Socialization-Position-Statement-FINAL.pdf', 'https://avsab.org/wp-content/uploads/2021/08/AVSAB-Humane-Dog-Training-Position-Statement-2021.pdf']::text[]) on conflict (id) do nothing;
insert into public.content_versions(id, content_id, version, title, body, min_age_weeks, max_age_weeks, status, sources) values ('62000000-0000-4000-8000-000000000006'::uuid, '61000000-0000-4000-8000-000000000006'::uuid, 1, 'Hjälp valpen att vara själv en liten stund', '## Börja med trygghet hemma

Välj en lugn plats där valpen kan vila och ha vatten. Låt platsen vara trevlig även när du är hemma, så att den inte bara förknippas med att du går.

Börja med lite avstånd medan du fortfarande är hemma. Håll övningen så enkel att valpen kan vara lugn och återvänd innan den blir orolig. Gör det gradvis och utifrån just din valps reaktion; det finns ingen minutplan som passar alla.

Om valpen verkar orolig, gör det lättare nästa gång och återgå till det senaste läge där den var lugn. Om oron kvarstår eller är kraftig, kontakta veterinär först. Efter medicinsk bedömning kan veterinären vid behov hänvisa till kvalificerad, belöningsbaserad beteendehjälp. Den här guiden förebygger inte eller behandlar garanterat separationsrelaterade problem.', 27, 52, 'draft', ARRAY['https://www.bluecross.org.uk/advice/dog/behaviour-and-training/preventing-separation-anxiety-in-puppies', 'https://www.rspca.org.uk/adviceandwelfare/pets/dogs/training/leftalone', 'https://avsab.org/wp-content/uploads/2021/08/AVSAB-Humane-Dog-Training-Position-Statement-2021.pdf']::text[]) on conflict (id) do nothing;
insert into public.content_versions(id, content_id, version, title, body, min_age_weeks, max_age_weeks, status, sources) values ('62000000-0000-4000-8000-000000000007'::uuid, '61000000-0000-4000-8000-000000000007'::uuid, 1, 'Så fungerar vikthistoriken', '## Lägg till en viktpost

Under Hälsa kan du registrera hundens vikt i kilo och ange datum. Du kan rätta eller radera en post och se dina registrerade vikter i datumordning.

Uppgifterna är ägarregistrerade. Tassla kontrollerar inte om vikten är lämplig, tolkar inte förändringar och ersätter inte en veterinärjournal. Vid frågor om hundens vikt eller tillväxt kan du kontakta veterinär.', 0, null, 'draft', ARRAY['repo://src/features/health/README.md', 'repo://src/features/health/HealthScreen.tsx', 'https://www.rspca.org.uk/adviceandwelfare/pets/dogs/health/puppycare']::text[]) on conflict (id) do nothing;
insert into public.content_versions(id, content_id, version, title, body, min_age_weeks, max_age_weeks, status, sources) values ('62000000-0000-4000-8000-000000000008'::uuid, '61000000-0000-4000-8000-000000000008'::uuid, 1, 'Registrera en utförd vaccination eller ett veterinärbesök', '## Din egen historik

I Hälsa kan du lägga till en post för en vaccination som redan har utförts eller ett veterinärbesök som redan har ägt rum. Ange datum och lägg vid behov till en kort anteckning. Du kan senare ändra eller radera posten.

Uppgifterna är registrerade av dig. De är inte en verifierad journal, ett officiellt vaccinationskort eller ett råd om när nästa vårdbesök ska ske. Fråga veterinär om vaccinationer, symtom eller vård.', 0, null, 'draft', ARRAY['repo://src/features/health/README.md', 'repo://src/features/health/HealthHistoryScreen.tsx', 'https://www.rspca.org.uk/adviceandwelfare/pets/dogs/health/puppycare']::text[]) on conflict (id) do nothing;
insert into public.content_versions(id, content_id, version, title, body, min_age_weeks, max_age_weeks, status, sources) values ('62000000-0000-4000-8000-000000000009'::uuid, '61000000-0000-4000-8000-000000000009'::uuid, 1, 'Trygg hantering i små steg', 'Öva bara när hunden verkar lugn. Belöna frivilligt deltagande och låt hunden gå undan. Stegen är förslag, inte en kalender. Tolka kroppssignaler i sitt sammanhang och tillsammans; en enstaka signal är inte en diagnos. Om hunden visar obehag: avbryt, ge utrymme och återgå nästa gång till ett enklare steg. Vid ihållande oro eller svår hantering, be veterinär om vägledning.', 8, null, 'draft', ARRAY['https://avsab.org/wp-content/uploads/2021/08/AVSAB-Humane-Dog-Training-Position-Statement-2021.pdf', 'https://avsab.org/resources/position-statements/', 'https://www.rspca.org.uk/adviceandwelfare/pets/dogs/behaviour/understanding']::text[]) on conflict (id) do nothing;
insert into public.content_versions(id, content_id, version, title, body, min_age_weeks, max_age_weeks, status, sources) values ('62000000-0000-4000-8000-000000000010'::uuid, '61000000-0000-4000-8000-000000000010'::uuid, 1, 'Utforska miljön med trygghet', 'Erbjud vardagens miljöer och ljud i en takt där hunden kan känna sig trygg. Låt den observera, närma sig eller gå undan. Belöna lugn, frivillig utforskning; tvinga inte fram kontakt. Om hunden verkar rädd eller överväldigad, stoppa exponeringen, skapa avstånd och gör nästa försök enklare. Tolka kroppssignaler i sitt sammanhang och tillsammans; en enstaka signal är inte en diagnos. Programmet ersätter inte individuell rådgivning.', 8, null, 'draft', ARRAY['https://www.rspca.org.uk/adviceandwelfare/pets/dogs/health/puppycare', 'https://avsab.org/wp-content/uploads/2024/12/Puppy-Socialization-Position-Statement-FINAL.pdf', 'https://avsab.org/wp-content/uploads/2021/08/AVSAB-Humane-Dog-Training-Position-Statement-2021.pdf', 'https://www.rspca.org.uk/adviceandwelfare/pets/dogs/behaviour/understanding']::text[]) on conflict (id) do nothing;
insert into public.content_versions(id, content_id, version, title, body, min_age_weeks, max_age_weeks, status, sources) values ('62000000-0000-4000-8000-000000000011'::uuid, '61000000-0000-4000-8000-000000000011'::uuid, 1, 'Öva på att vara själv i hundens takt', 'Gör den valda viloplatsen trygg även när du är hemma. Börja med lite avstånd och håll varje övning så enkel att hunden verkar lugn. Gå vidare först när just din hund är bekväm; programmet har inga fasta minuter eller kalendersteg. Om hunden blir orolig: avbryt, gå tillbaka till senaste läget där den var lugn och kontakta veterinär först vid kvarstående eller kraftig oro. Efter medicinsk bedömning kan veterinären vid behov hänvisa till kvalificerad, belöningsbaserad beteendehjälp.', 8, null, 'draft', ARRAY['https://www.bluecross.org.uk/advice/dog/behaviour-and-training/preventing-separation-anxiety-in-puppies', 'https://www.rspca.org.uk/adviceandwelfare/pets/dogs/training/leftalone', 'https://avsab.org/wp-content/uploads/2021/08/AVSAB-Humane-Dog-Training-Position-Statement-2021.pdf']::text[]) on conflict (id) do nothing;
