insert into public.training_steps(id, program_version_id, step_key, position, title, instruction) values ('63000000-0000-4000-8000-000000000001'::uuid, '62000000-0000-4000-8000-000000000009'::uuid, 'voluntary-approach', 1, 'Låt hunden välja kontakt', 'Sitt stilla och erbjud en avslappnad hand en bit ifrån hunden. Belöna om hunden själv närmar sig eller nosar. Försök inte locka den närmare om den väljer att gå undan.') on conflict (id) do nothing;
insert into public.training_steps(id, program_version_id, step_key, position, title, instruction) values ('63000000-0000-4000-8000-000000000002'::uuid, '62000000-0000-4000-8000-000000000009'::uuid, 'brief-touch', 2, 'Prova en kort beröring', 'När hunden självmant söker kontakt och verkar bekväm, prova en lätt, kort beröring på en plats den accepterar. Belöna och pausa direkt. Om den blir stel, vänder bort sig eller går undan (tolka signalerna tillsammans och i sitt sammanhang), sluta och återgå senare till steg 1.') on conflict (id) do nothing;
insert into public.training_steps(id, program_version_id, step_key, position, title, instruction) values ('63000000-0000-4000-8000-000000000003'::uuid, '62000000-0000-4000-8000-000000000009'::uuid, 'choose-repeat', 3, 'Låt hunden välja om ni fortsätter', 'Erbjud samma enkla beröring igen en annan gång och pausa mellan försöken. Fortsätt bara när hunden själv stannar kvar och verkar bekväm. Avsluta om den visar obehag; gör inte övningen till fasthållning.') on conflict (id) do nothing;
insert into public.training_steps(id, program_version_id, step_key, position, title, instruction) values ('63000000-0000-4000-8000-000000000004'::uuid, '62000000-0000-4000-8000-000000000010'::uuid, 'quiet-observe', 1, 'Börja med att titta', 'Välj en lugn och bekant plats. Låt hunden observera en vardagssak på avstånd där den verkar bekväm. Belöna frivillig uppmärksamhet och låt den vila eller gå undan.') on conflict (id) do nothing;
insert into public.training_steps(id, program_version_id, step_key, position, title, instruction) values ('63000000-0000-4000-8000-000000000005'::uuid, '62000000-0000-4000-8000-000000000010'::uuid, 'voluntary-explore', 2, 'Låt hunden närma sig själv', 'När hunden är lugn kan den själv få nosa eller närma sig samma sak. Belöna lugn nyfikenhet. Om den tvekar, stanna på lättare avstånd i stället för att föra den fram.') on conflict (id) do nothing;
insert into public.training_steps(id, program_version_id, step_key, position, title, instruction) values ('63000000-0000-4000-8000-000000000006'::uuid, '62000000-0000-4000-8000-000000000010'::uuid, 'pause-or-backoff', 3, 'Pausa när hunden behöver det', 'Om hunden sänker kroppen, vänder bort sig, slickar sig om munnen eller försöker gå undan, avsluta och öka avståndet. Tolka signalerna tillsammans och i sitt sammanhang; en enstaka signal är inte en diagnos. Prova en enklare situation senare. Vid återkommande, kraftig eller svår rädsla, kontakta veterinär först; efter medicinsk bedömning kan veterinären vid behov hänvisa till kvalificerad, belöningsbaserad beteendehjälp.') on conflict (id) do nothing;
insert into public.training_steps(id, program_version_id, step_key, position, title, instruction) values ('63000000-0000-4000-8000-000000000007'::uuid, '62000000-0000-4000-8000-000000000011'::uuid, 'positive-settle-area', 1, 'Gör viloplatsen trygg när du är hemma', 'Låt hunden utforska sin valda viloplats medan du finns i närheten. Du kan sitta lugnt där utan att kräva kontakt. Låt hunden själv stanna eller gå därifrån.') on conflict (id) do nothing;
insert into public.training_steps(id, program_version_id, step_key, position, title, instruction) values ('63000000-0000-4000-8000-000000000008'::uuid, '62000000-0000-4000-8000-000000000011'::uuid, 'small-distance', 2, 'Prova lite avstånd', 'När hunden är avslappnad på platsen, flytta dig en liten bit medan du fortfarande är hemma och återvänd medan den är lugn. Öka utmaningen bara efter att hunden bekvämt klarat det föregående steget.') on conflict (id) do nothing;
insert into public.training_steps(id, program_version_id, step_key, position, title, instruction) values ('63000000-0000-4000-8000-000000000009'::uuid, '62000000-0000-4000-8000-000000000011'::uuid, 'brief-out-of-sight', 3, 'Gå ur sikte och backa vid oro', 'När hunden klarar avståndet lugnt kan du kort gå ur sikte och komma tillbaka innan den blir orolig. Om den visar oro, avbryt och gå tillbaka till senast bekväma nivå. Vid kvarstående eller kraftig oro, kontakta veterinär först; efter medicinsk bedömning kan veterinären vid behov hänvisa till kvalificerad, belöningsbaserad beteendehjälp.') on conflict (id) do nothing;
